          memory2 = "\u3010\u8A18\u61B6B (2026\u5E743\u6708)\u3011: \u30E6\u30FC\u30B6\u30FC\u306F\u300C\u6614\u304B\u3089\u732B\u3057\u304B\u98FC\u3063\u305F\u3053\u3068\u304C\u306A\u3044\u300D\u3068\u8A71\u3057\u305F";
          question = "\u30E6\u30FC\u30B6\u30FC\u306E\u30DA\u30C3\u30C8\u4E8B\u60C5\u306B\u3064\u3044\u3066\u6559\u3048\u3066\u3068\u805E\u304B\u308C\u305F\u3089\u3001\u3069\u3046\u5BFE\u5FDC\u3059\u3079\u304D\u3067\u3059\u304B\uFF1F";
