var STORAGE_KEY11 = "miki_meta_memory_state";
var MetaMemoryService = class {
  params = {
    vectorWeight: 0.5,
    linkWeight: 0.3,
    tagWeight: 0.2,
    maxLinkDepth: 2,
    minScoreThreshold: 6
  };
  isLoaded = false;
  constructor() {
    this.load();
  }
  load() {
    if (this.isLoaded) return;
    try {
      const raw = storageService.getItem(STORAGE_KEY11);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed.vectorWeight === "number") {
          this.params = { ...this.params, ...parsed };
        }
      }
      this.isLoaded = true;
    } catch (e) {
    }
  }
  save() {
    try {
      storageService.setItem(STORAGE_KEY11, JSON.stringify(this.params));
    } catch (e) {
    }
  }
  getParams() {
    this.load();
    return { ...this.params };
  }
  /**
   * クエリの文脈種別に応じた最適な想起比率を算出 (第2章⑧ & 第3章5節)
   */
  getAdaptiveParamsForContext(contextType) {
    this.load();
    const base = { ...this.params };
    switch (contextType) {
      case "code":
      case "logic":
        return {
          vectorWeight: 0.3,
          linkWeight: 0.4,
          tagWeight: 0.3,
          maxLinkDepth: base.maxLinkDepth,
          minScoreThreshold: 7
        };
      case "chat":
      default:
        return {
          vectorWeight: 0.6,
          linkWeight: 0.2,
          tagWeight: 0.2,
          maxLinkDepth: 2,
          minScoreThreshold: 5
        };
    }
  }
  /**
   * ユーザー訂正や高評価フィードバックを元に想起比率を微調整
   */
  adaptWeightsFromFeedback(wasCorrection) {
    this.load();
    if (wasCorrection) {
      this.params.vectorWeight = Math.max(0.2, Number((this.params.vectorWeight - 0.05).toFixed(2)));
      this.params.tagWeight = Math.min(0.5, Number((this.params.tagWeight + 0.05).toFixed(2)));
    } else {
      this.params.vectorWeight = Math.min(0.7, Number((this.params.vectorWeight + 0.02).toFixed(2)));
      this.params.tagWeight = Math.max(0.1, Number((this.params.tagWeight - 0.02).toFixed(2)));
    }
    this.save();
  }
};
var metaMemoryService = new MetaMemoryService();

