var AiderEngineService = class {
  /**
   * 1. Aider Repo Map を取得
   */
  async fetchRepoMap() {
    try {
      const res = await fetch(apiUrl("/api/aider/repo-map"));
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      systemLogger.info("SELF_IMPROVEMENT", `[Aider Repo Map] ${data.scannedFilesCount} \u30D5\u30A1\u30A4\u30EB / ${data.totalSymbolsCount} \u30B7\u30F3\u30DC\u30EB\u8D70\u67FB\u5B8C\u4E86`);
      return data;
    } catch (err) {
      systemLogger.warn("SELF_IMPROVEMENT", `fetchRepoMap\u5931\u6557: ${SERVER_UNAVAILABLE_MESSAGE}`);
      return {
        success: false,
        scannedFilesCount: 0,
        totalSymbolsCount: 0,
        entries: [],
        formattedRepoMap: `=== AIDER REPOSITORY MAP ===
${SERVER_UNAVAILABLE_MESSAGE}
`,
        generatedAt: Date.now()
      };
    }
  }
  /**
   * 2. Search/Replace ブロック差分置換
   */
  async applySearchReplace(filePath, searchBlock, replaceBlock) {
    try {
      const res = await fetch(apiUrl("/api/aider/search-replace"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ filePath, searchBlock, replaceBlock })
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        return { success: false, error: data.error || SERVER_UNAVAILABLE_MESSAGE };
      }
      systemLogger.info("SELF_IMPROVEMENT", `[Aider Diff] ${data.diffSummary}`);
      return data;
    } catch (err) {
      return { success: false, error: SERVER_UNAVAILABLE_MESSAGE };
    }
  }
  /**
   * 3. 自動エラー自己修復ループ
   */
  async autoHealCode(code, filename = "module.ts") {
    try {
      const res = await fetch(apiUrl("/api/aider/auto-heal"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code, filename })
      });
      const data = await res.json();
      systemLogger.info("SELF_IMPROVEMENT", `[Aider Auto-Heal] \u4FEE\u5FA9\u8A66\u884C: ${data.attempts}\u56DE, \u89E3\u6C7A: ${data.healed}`);
      return data;
    } catch (err) {
      return {
        success: false,
        healed: false,
        attempts: 1,
        cleanCode: code,
        repairHistory: [{ attempt: 1, error: SERVER_UNAVAILABLE_MESSAGE, fixApplied: "\u4FEE\u5FA9\u4E0D\u53EF" }],
        finalErrorCount: 1
      };
    }
  }
  /**
   * 4. コミット履歴取得 & コミット & ロールバック
   */
  async fetchCommits() {
    try {
      const res = await fetch(apiUrl("/api/aider/commits"));
      if (!res.ok) return [];
      const data = await res.json();
      return data.commits || [];
    } catch (e) {
      return [];
    }
  }
  async createCommit(message, files) {
    try {
      const res = await fetch(apiUrl("/api/aider/commit"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message, files })
      });
      if (!res.ok) return null;
      const data = await res.json();
      systemLogger.info("SELF_IMPROVEMENT", `[Aider Git Commit] [${data.commit.hash}] ${data.commit.message}`);
      return data.commit;
    } catch (e) {
      return null;
    }
  }
  async rollbackCommit(hash9) {
    try {
      const res = await fetch(apiUrl("/api/aider/rollback"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ hash: hash9 })
      });
      const data = await res.json();
      systemLogger.info("SELF_IMPROVEMENT", `[Aider Rollback] \u30B3\u30DF\u30C3\u30C8 [${hash9}] \u3092\u7269\u7406\u5FA9\u5143\u3057\u307E\u3057\u305F: ${data.message}`);
      return { success: data.success, message: data.message || data.error, restoredFiles: data.restoredFiles };
    } catch (err) {
      return { success: false, message: SERVER_UNAVAILABLE_MESSAGE };
    }
  }
};
