var KEY19 = "miki_code_template_library_v1";
var CodeTemplateLibraryService = class {
  templates = [];
  constructor() {
    this.load();
  }
  resolve(language, purpose, requiredCapabilities = []) {
    const words = purpose.toLowerCase().split(/[^a-z0-9_぀-ヿ㐀-鿿]+/).filter(Boolean);
    const matched = this.templates.filter((item) => item.language === language && words.some((word) => item.purpose.toLowerCase().includes(word)));
    const covered = new Set(matched.flatMap((item) => item.invariants));
    const missingCapabilities = requiredCapabilities.filter((capability) => !covered.has(capability));
    return {
      matched,
      missingCapabilities,
      researchQuestions: missingCapabilities.map((capability) => `\u80FD\u529B\u300C${capability}\u300D\u3092\u5B9F\u88C5\u30FB\u691C\u8A3C\u3059\u308B\u305F\u3081\u306E\u516C\u5F0F\u4ED5\u69D8\u3001\u65E2\u5B58\u90E8\u54C1\u3001\u53CD\u4F8B\u3001\u5B9F\u884C\u8A3C\u62E0\u306F\u4F55\u304B`)
    };
  }
  registerCandidate(template) {
    if (template.status === "VERIFIED" && template.requiredEvidence.length === 0) return false;
    const index = this.templates.findIndex((item) => item.id === template.id);
    if (index >= 0) this.templates[index] = template;
    else this.templates.push(template);
    this.save();
    return true;
  }
  getAll() {
    return this.templates.map((item) => ({ ...item, invariants: [...item.invariants], requiredEvidence: [...item.requiredEvidence] }));
  }
  load() {
    const seeds = [
      { id: "ts.service", language: "typescript", purpose: "\u72B6\u614B\u3092\u6301\u3064\u30B5\u30FC\u30D3\u30B9", status: "SEED", template: "export class {{ServiceName}} {\n  public execute(input: {{InputType}}): {{OutputType}} {\n    {{BODY}}\n  }\n}\n", invariants: ["explicit_input", "explicit_output", "no_fixed_pass"], requiredEvidence: ["ts_parse", "unit_test"] },
      { id: "ts.api_route", language: "typescript", purpose: "\u691C\u8A3C\u4ED8\u304DAPI\u30EB\u30FC\u30C8", status: "SEED", template: "app.post('{{PATH}}', async (req, res) => {\n  {{VALIDATE_INPUT}}\n  {{BODY}}\n});\n", invariants: ["validate_input", "fail_closed"], requiredEvidence: ["ts_parse", "route_test"] },
      { id: "vba.full_module", language: "vba", purpose: "\u6A19\u6E96\u30E2\u30B8\u30E5\u30FC\u30EB\u5168\u4F53", status: "SEED", template: "Option Explicit\n\nPublic Sub {{MACRO_NAME}}()\n    {{BODY}}\nEnd Sub\n", invariants: ["Option Explicit", "block_if_only", "no_goto", "no_labels", "full_module"], requiredEvidence: ["vba_static_verification", "secondary_string_verification"] },
      { id: "kotlin.capacitor_plugin", language: "kotlin", purpose: "Capacitor Native Plugin", status: "SEED", template: '@CapacitorPlugin(name = "{{PLUGIN_NAME}}")\nclass {{CLASS_NAME}} : Plugin() {\n    {{BODY}}\n}\n', invariants: ["explicit_plugin_name", "reject_on_failure"], requiredEvidence: ["kotlin_compile", "android_contract", "device_test"] },
      { id: "shell.installer", language: "shell", purpose: "\u518D\u73FE\u53EF\u80FD\u306A\u5C0E\u5165\u30B9\u30AF\u30EA\u30D7\u30C8", status: "SEED", template: "#!/usr/bin/env bash\nset -euo pipefail\n{{BODY}}\n", invariants: ["fail_closed", "pinned_version", "hash_verification"], requiredEvidence: ["shell_parse", "clean_install_test"] }
    ];
    try {
      const raw = storageService.getItem(KEY19);
      const saved = raw ? JSON.parse(raw) : [];
      this.templates = Array.isArray(saved) && saved.length > 0 ? saved : seeds;
    } catch {
      this.templates = seeds;
    }
  }
  save() {
    storageService.setItem(KEY19, JSON.stringify(this.templates));
  }
};
var codeTemplateLibraryService = new CodeTemplateLibraryService();

