var KEY20 = "miki_counterfactual_work_v1";
var CounterfactualWorkSimulatorService = class {
  history = [];
  constructor() {
    try {
      const r = storageService.getItem(KEY20);
      const p = r ? JSON.parse(r) : [];
      if (Array.isArray(p)) this.history = p;
    } catch {
    }
  }
  save() {
    storageService.setItem(KEY20, JSON.stringify(this.history.slice(-200)));
  }
  shouldSimulate(trigger) {
    return trigger === "FAILURE" || trigger === "HIGH_COST" || trigger === "IMPORTANT";
  }
  simulate(taskId, selectedRoute, alternatives, trigger) {
    if (!this.shouldSimulate(trigger) || alternatives.length === 0) return null;
    const compared = alternatives.map((route) => ({
      routeId: route.id,
      costDelta: selectedRoute.estimatedCost - route.estimatedCost,
      riskDelta: selectedRoute.risk - route.risk,
      expectedImprovement: Math.max(-1, Math.min(1, (selectedRoute.risk - route.risk) * 0.6 + (selectedRoute.estimatedCost - route.estimatedCost) * 0.01)),
      confidence: route.evidenceIds?.length ? Math.min(0.9, 0.5 + route.evidenceIds.length * 0.05) : 0.25
    }));
    const record = { id: `CWS-${Date.now().toString(36)}`, taskId, trigger, selectedRoute, alternatives, compared, status: "VIRTUAL_ONLY", createdAt: Date.now() };
    this.history.unshift(record);
    this.save();
    systemLogger.info("SELF_IMPROVEMENT", `[\u7B2C63\u7AE0] \u53CD\u5B9F\u4EEE\u60F3\u4F5C\u696D\u6BD4\u8F03: ${taskId} / \u5019\u88DC=${alternatives.length} / \u4EEE\u60F3\u8A55\u4FA1\u306E\u307F`);
    return record;
  }
  getHistory(taskId) {
    return this.history.filter((x) => !taskId || x.taskId === taskId);
  }
};
var counterfactualWorkSimulatorService = new CounterfactualWorkSimulatorService();

